function createSimpleUseState(initialValue) {
  let state = typeof initialValue === 'function' ? initialValue() : initialValue;

  function getState() {
    return state;
  }

  function setState(action) {
    if (typeof action === 'function') {
      state = action(state);
    } else {
      state = action;
    }
  }

  return [getState, setState];
}
